head.script:
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#inputCalendar1_input', 'key-sequence', {
        sequence: "12345678"
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#input1', 'key-sequence', {
        sequence: "111"
    })
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 inputCalendar에 8자리를 입력 후 9자리 이상으로 더 입력한다.
    //1. After executing the sample, input 8 digits in inputCalendar and input it more than 9 digits.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_input').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify 1. 8자리까지 입력되어지고 9자리 입력 시 focus가 inputbox로 이동되어진다.
    //1. Enter up to 8 digits and when 9 digits are entered, focus is moved to input box.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#input1').hasClass('w2input_focus')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step2. inputbox에 3자리를 입력 후 4자리 이상으로 더 입력한다.
    //2. Enter 3 digits in the input box and enter 4 digits or more.
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify2. 3자리까지 입력되어지고 4자리 입력 시 focus가 inputCalendar로 이동되어진다.
    //2. Up to 3 digits are entered. When 4 digits are entered, the focus is shifted to inputCalendar.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#inputCalendar1_input').hasClass('w2inputCalendar_focus')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 다시 inputCalendar에 9자리 이상을 입력한다.
    //3. Input more than 9 digits in inputCalendar again.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_input').value = ''");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify 3. 9자리 입력 시 다시 focus가 inputbox로 이동되어진다.(이전에는 9자리 이상 입력되어지고 focus는 이동되지 않음)
    //3. When 9 digits are entered, the focus is moved to the input box (previously 9 digits or more are entered and the focus is not moved)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#input1').hasClass('w2input_focus')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 13-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
